CREATE POLICY "ledger_driver_history" ON "ledger_journals" AS PERMISSIVE FOR SELECT TO public USING (current_setting('rove.actor_role',true)='driver' AND NULLIF(current_setting('rove.ledger_owner',true),'')=NULLIF(current_setting('rove.actor_id',true),'') AND "ledger_journals"."kind" IN ('allocation','refund_loss_allocation','dispute_loss_allocation') AND EXISTS(SELECT 1 FROM public.rides r WHERE r.id="ledger_journals"."ride_id" AND r.driver_id=NULLIF(current_setting('rove.actor_id',true),'')::uuid));